import{c as l,b as d,e as n,d as t,f as i,h as c,g as s,u as o,x as p,G as h,I as a}from"./index-mSZoPfFT.js";import"./wallet-DAshJcR-.js";const u=l("ArrowRightIcon",[["path",{d:"M5 12h14",key:"1ays0h"}],["path",{d:"m12 5 7 7-7 7",key:"xquz4c"}]]),m={class:"guide"},f={id:"quickstart",class:"chapter"},g={class:"prose"},v={id:"roadmap",class:"chapter"},y={class:"prose"},b={class:"doc-links"},k={class:"cta cta-ghost",href:"/docs/business-plan.pdf",target:"_blank"},x={class:"cta cta-ghost",href:"/docs/business-plan.md"},I={__name:"Learn",setup(w){return(T,e)=>{const r=p("RouterLink");return h(),d("div",m,[e[10]||(e[10]=n('<section class="overture guide-overture"><div class="overture-grid"><div><p class="tag">THE Leverix FIELD GUIDE</p><h1 class="shout">Context before conviction.</h1><p class="standfirst"> Understand the markets, the mechanics, and what this first release can do. </p></div></div></section><div class="chapter-ticker"><a href="#quickstart">Get started</a><a href="#mechanics">The testnet model</a><a href="#sessions">Market sessions</a><a href="#risk">Risk &amp; limitations</a><a href="#roadmap">What comes next</a></div>',2)),t("section",f,[e[2]||(e[2]=t("p",{class:"chapter-index"},"01 / QUICKSTART",-1)),t("div",g,[e[1]||(e[1]=n('<h2>Your first test position.</h2><ol><li><strong>Connect an Ethereum wallet.</strong> Use an injected browser wallet, or open this site in your mobile wallet browser. We support EIP-6963 wallet discovery. </li><li><strong>Switch to Robinhood Chain Testnet.</strong> Chain ID 46630. You need test ETH for gas. Get it from the <a href="https://faucet.testnet.chain.robinhood.com" target="_blank" rel="noopener noreferrer">official faucet ↗</a>. </li><li><strong>Claim free dUSD.</strong> The experimental faucet issues 10,000 test tokens per wallet every 24 hours. These tokens cannot be redeemed for money. </li><li><strong>Deposit collateral.</strong> Approve the exact amount, then confirm the deposit in your wallet. </li><li><strong>Open a long or short.</strong> Choose a synthetic market and 1–20× leverage. Check entry, margin and freshness. Confirm the transaction. </li><li><strong>Close and withdraw.</strong> Settlement returns remaining margin and capped synthetic PnL to your available collateral balance. Withdraw that balance to your wallet. </li></ol>',2)),i(r,{class:"cta cta-solid",to:"/trade"},{default:c(()=>[e[0]||(e[0]=s("Open the terminal ",-1)),i(o(a),{size:17})]),_:1})])]),e[11]||(e[11]=n('<section id="mechanics" class="chapter"><p class="chapter-index">02 / THE ACTUAL MODEL</p><div class="prose"><h2>Simple enough to inspect.</h2><p> 32 synthetic equity benchmark markets, including NIKKEI, DAX and FTSE100. The displayed editorial examples are fixed fixtures. Contract prices are separately read from the chain and updated by the test operator. There is no connection to a live exchange price feed. </p><div class="formula"><strong>Position PnL</strong><code>margin × leverage × (exit − entry) / entry</code><p> The sign reverses for a short position. Settlement is capped between a loss of 100% and a gain of 100% of position margin. This is a limited simulation, not the payoff of an uncapped perpetual future. </p></div><p> Positions use isolated margin, 1–20× leverage and an operator-controlled demo price feed. Prices older than 15 minutes cannot be used for ordinary execution. The liquidation threshold is a 90% loss of margin. There are no funding payments or trading fees in this sandbox. </p><p> The prototype reserves maximum profit against test liquidity before opening positions. Pausing prevents new risk while preserving the contract’s supported exit paths. This is a test of the transaction lifecycle, not proof of mainnet solvency or security. </p></div></section><section id="sessions" class="chapter"><p class="chapter-index">03 / A WORLD WITH OPENING HOURS</p><div class="prose"><h2>An open interface. Real market hours.</h2><p> A stock benchmark is not continuously priced outside its underlying exchange session. The intended live product will show the session state and last valid timestamp for every market. Out-of-session orders will be queued against reserved margin and filled only after a fresh, valid price becomes available, with user-defined slippage and expiry. </p><p> Exchange calendars, local daylight saving changes, holidays, interruptions and Japan’s midday break matter. The current synthetic testnet does not implement a live-market order queue. It must not be used to infer out-of-hours prices. </p></div></section><section id="risk" class="chapter"><p class="chapter-index">04 / KNOW THE LIMITS</p><div class="prose"><h2>What you should know.</h2><ul><li>Experimental, unaudited contracts. Use worthless test tokens only.</li><li> The operator controls mock prices, market availability and pause controls. This is not a decentralized oracle. </li><li> Leverage amplifies losses. In this sandbox, liquidation is possible at 90% margin loss and PnL is capped at ±100% of margin. </li><li>Public RPCs, the sequencer, wallet providers and explorers may become unavailable.</li><li> Leverix is independent of Robinhood. Network compatibility does not imply affiliation or endorsement. </li><li> Benchmark names are descriptive. No index data license, issuer partnership or investment recommendation is implied. </li><li> Wallet connection does not create a custody account. Optional ownership verification is local to this browser session; no backend authentication session is issued. </li></ul></div></section>',3)),t("section",v,[e[9]||(e[9]=t("p",{class:"chapter-index"},"05 / THE ROAD AHEAD",-1)),t("div",y,[e[5]||(e[5]=t("h2",null,"Build confidence before scale.",-1)),e[6]||(e[6]=t("p",null,[t("strong",null,"Now:"),s(" validate onboarding and the complete test-collateral lifecycle. Collect direct feedback, test contract invariants, and document the limits. ")],-1)),e[7]||(e[7]=t("p",null,[t("strong",null,"Next:"),s(" integrate licensed reference feeds, holiday-aware sessions, queued orders, and a production risk engine. Commission external security reviews and engage qualified legal counsel. ")],-1)),e[8]||(e[8]=t("p",null,[t("strong",null,"Before any live launch:"),s(" establish jurisdiction eligibility, resilient oracles, market maker commitments, capped rollout parameters and incident response. No launch date or return is promised. ")],-1)),t("div",b,[t("a",k,[e[3]||(e[3]=s("Business plan PDF ",-1)),i(o(a),{size:17})]),t("a",x,[e[4]||(e[4]=s("Source document ",-1)),i(o(u),{size:17})])])])])])}}};export{I as default};
